head.script:
scwin.screenId = "jldbnf60201";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "if_sriBndTpCd", fn: function(){ return ((dma_result.get("sriBndTpCd") ?? (() => { throw new Error("unresolved:" + "result.sriBndTpCd"); })()) === '4'); } }, { id: "if_sriBndTpCd_2", fn: function(){ return ((dma_result.get("sriBndTpCd") ?? (() => { throw new Error("unresolved:" + "result.sriBndTpCd"); })()) === '4'); } }, { id: "c_when_131", fn: function(){ return ((dma_result.get("sriBndTpCd") ?? (() => { throw new Error("unresolved:" + "result.sriBndTpCd"); })()) !== '4'); } }, { id: "c_otherwise_170", fn: function(){ return (!(((dma_result.get("sriBndTpCd") ?? (() => { throw new Error("unresolved:" + "result.sriBndTpCd"); })()) !== '4'))); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        for (var __r = 0, __n = $c.util.getComponent('dlt_dtlList').getTotalRow(); __r < __n; __r++) {let i = __r; 

        }
        for (var __r = 0, __n = $c.util.getComponent('dlt_dtlList').getTotalRow(); __r < __n; __r++) {let i = __r; /* 수동 전환 필요: DOM 관용구 $(this) 잔존 — 행 순회 안에서 해석 못 함(D19-b) */
            $(this).attr("id", "sri_bnd_prog_stat_cd" + i);
        }
        const sToday = WebSquare.date.getCurrentServerDate("yyyyMMdd");
        const sThisYear = sToday.substring(0, 4);
        $c.util.getComponent('slc_suplyFndUseRptYy').setValue(sThisYear);
        for (var __r = 0, __n = $c.util.getComponent('dlt_dtlList').getTotalRow(); __r < __n; __r++) {let i = __r; 
            let t = $c.util.getComponent('dlt_dtlList').getCellData(__r, 'lstObservDd');
            t = t.replace(/-/gi, '');
            if (t >= sToday) {
                $("#sri_bnd_prog_stat_cd" + i).val("1");
                $("#sri_bnd_prog_stat_cd" + i + " option[value='2']").remove();
                $("#sri_bnd_prog_stat_cd" + i + " option[value='3']").remove();
            } else {
                $("#sri_bnd_prog_stat_cd" + i + " option:first").remove();
            }
        }
        $('#slc_suplyFndUseRptRndTpCd').change(function() {
                if (this.value === "3") {
                    $('#ipt_efctRptIncldY').prop('checked', true);
                } else {
                    $('#ipt_efctRptIncldN').prop('checked', true);
                }
        });
        $('input[name=efct_rpt_incld_yn_rdo]:radio').change(async function() {
                if (this.value === "Y" && $c.util.getComponent('slc_suplyFndUseRptRndTpCd').getValue() !== "3") {
                    await $c.win.alert("최종보고인 경우만 선택 할 수 있습니다.");
                    $('#ipt_efctRptIncldN').prop('checked', true);
                }
        });
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf60201.onpageload' }); }
};

/**
 * @method
 * @name scwin.init_loadList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.dmenus = undefined; try { scwin.dmenus = /* sdd-asis-lifecycle:begin dmenus — as-is 원문 본문(전환 이관 · 포팅 적용됨) */{
        "bmenu":9
        ,"mmenu":1
    }/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldbnf60201' }); }

scwin.v_unused_amt = '' + dma_result.get("unusedAmt") + '';

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_conds();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldbnf60201.onpageload' });
    }
};


