/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.save = async function () {
    /* sdd-asis-lifecycle:begin fn_save — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!await scwin.checkData()) {
        return;
    } else {
        if (!await $c.win.confirm("신청하시겠습니까?")) {
            return false;
        }
    }
    const fm = (document.SendForm || { elements: [] });
    /* 수동 전환 필요: 이름 선택자 순회 [name=attach_file_tp_cd] — B3/B4 스펙 참조 없음(as-is 대조 필요) · to-be 에 돌 요소가 없다 */ $('input[name=attach_file_tp_cd]').each(function(i) {
            const tempVal = $("input[name=attach_file_tp_cd]:eq(" + i + ")").val();
            if (tempVal === "6") {
                if ($c.util.getComponent('slc_suplyFndUseRptRndTpCd').getValue()=== "1") {
                    $("input[name=attach_file_tp_cd]:eq(" + i + ")").val("9");
                } else {
                    if ($c.util.getComponent('slc_suplyFndUseRptRndTpCd').getValue()=== "2") {
                        $("input[name=attach_file_tp_cd]:eq(" + i + ")").val("10");
                    } else {
                        if ($c.util.getComponent('slc_suplyFndUseRptRndTpCd').getValue()=== "3") {
                            $("input[name=attach_file_tp_cd]:eq(" + i + ")").val("11");
                        }
                    }
                }
            } else {
                if (tempVal === "14") {
                    if ($c.util.getComponent('slc_suplyFndUseRptRndTpCd').getValue()=== "1") {
                        $("input[name=attach_file_tp_cd]:eq(" + i + ")").val("14");
                    } else {
                        if ($c.util.getComponent('slc_suplyFndUseRptRndTpCd').getValue()=== "2") {
                            $("input[name=attach_file_tp_cd]:eq(" + i + ")").val("15");
                        } else {
                            if ($c.util.getComponent('slc_suplyFndUseRptRndTpCd').getValue()=== "3") {
                                $("input[name=attach_file_tp_cd]:eq(" + i + ")").val("16");
                            }
                        }
                    }
                }
            }
    });
    $c.util.getComponent("dma_showSuplyFndUseRptListReq").set("apctTelNo", $c.util.getComponent('ipt_apctTelNo1').getValue()+ '-' + $c.util.getComponent('ipt_apctTelNo2').getValue()+ '-' + $c.util.getComponent('ipt_apctTelNo3').getValue());
    $c.util.getComponent("dma_showSuplyFndUseRptListReq").set("apctFaxNo", $c.util.getComponent('ipt_apctFaxNo1').getValue()+ '-' + $c.util.getComponent('ipt_apctFaxNo2').getValue()+ '-' + $c.util.getComponent('ipt_apctFaxNo3').getValue());
    $c.util.getComponent("dma_showSuplyFndUseRptListReq").set("encrypApctEmail", $c.util.getComponent('ipt_encrypApctEmail1').getValue()+ '@' + $c.util.getComponent('ipt_encrypApctEmail2').getValue());
    let efct_rpt_incld_yn = "";
    if ($c.util.getComponent('slc_suplyFndUseRptRndTpCd').getValue() === "3") {
        if ($c.util.getComponent('ipt_sriBndTpCd').getValue() === "4") {
            efct_rpt_incld_yn = "Y";
        } else {
            efct_rpt_incld_yn = $('input[name=efct_rpt_incld_yn_rdo]:checked').val();
        }
    } else {
        efct_rpt_incld_yn = "N";
    }
    $c.util.getComponent('ipt_efctRptIncldYn').setValue(efct_rpt_incld_yn);
    fm.action = "/sri/sribnd.do";
    $c.util.getComponent('dma_showSuplyFndUseRptListReq').set('method', "saveSuplyFndUseRptReg");
    await scwin.tx_fn_save();
    document.btn_save.setStyle("display", "none");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkData
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.checkData = async function () {
    /* sdd-asis-lifecycle:begin fn_checkData — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.SendForm || { elements: [] });
    const _now_time = dma_hiddenStore.get("areaNowTimer");
    const _isur_cd = $c.util.getComponent("dma_showSuplyFndUseRptListReq").get("isurCd");
    if (!applTmCheck('SRI_RPT', _now_time, _isur_cd)) {
        return false;
    }
    if (($c.util.getComponent('ipt_suplyFndUseRptExecuteAmt').getValue() == null ? '' : String($c.util.getComponent('ipt_suplyFndUseRptExecuteAmt').getValue())) === '') {
        await $c.win.alert("집행금액을 입력하세요.");
        $c.util.getComponent("ipt_suplyFndUseRptExecuteAmt").focus();
        return false;
    }
    const rowCnt = $("#tbl_file tr").length;
    for (let i = 0; i < rowCnt; i++) {
        if ($("input[name='attach_file_nm[" + i + "]']").val() === "") {
            const tempVal = $("input[name=attach_file_tp_cd]:eq(" + i + ")").val();
            if (tempVal === "6" || tempVal === "14") {
                await $c.win.alert("필수 파일을 선택하십시오.");
            } else {
                await $c.win.alert("기타 파일을 선택하십시오.");
            }
            console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return false;
        }
    }
    let file_size_sum = 0;
    const limitedSize = 200 * (1024 * 1024);
    file_size_sum = $("input[name='attachFiles[0]']")[0].files[0].size;
    if (file_size_sum > limitedSize) {
        await $c.win.alert(" 최대 파일업로드 허용용량 200MB를 초과하였습니다. \n\n 현재 용량은 " + Math.round(file_size_sum / (1024 * 1024)) + "MB입니다.");
        return false;
    }
    const rptTp = $c.util.getComponent('slc_suplyFndUseRptRndTpCd').getValue();
    const fst_rpt_yn = $c.util.getComponent('ipt_fstRptYn').getValue();
    const last_rpt_yn = $c.util.getComponent('ipt_lastRptYn').getValue();
    if (rptTp === "1" && fst_rpt_yn === "Y") {
        var msg = "이미 최초보고가 신청되었습니다." + "\n" + "보고구분을 확인하세요.";
        await $c.win.alert(msg);
        return false;
    }
    if (rptTp === "3" && last_rpt_yn === "Y") {
        var msg = "이미 최종보고가 신청되었습니다." + "\n" + "보고구분을 확인하세요.";
        await $c.win.alert(msg);
        return false;
    }
    if (!CheckReqInfo(fm)) {
        return false;
    } else {
        if (!scwin.CheckReqInfo_Cellphone(fm)) {
            return false;
        }
    }
    return true;
    /* sdd-asis-lifecycle:end */
};
